per_step.command:
cat << 'EOF' > /tmp/calc_all.sh
#!/bin/bash
compute_stats() {
  local deltas=$(for f in /app/data/neurocure_2024/*.json /app/data/quarantine/*.json; do jq -r '.post_treatment_score - .baseline_cognition_score' "$f" 2>/dev/null; done)
  echo "$deltas" | awk 'BEGIN{n=0;sum=0;sumsq=0}
  /^[+-]?[0-9]/ {n++; sum+=$1; sumsq+=$1*$1}
  END {
    if(n>0) {
      mean=sum/n;
      if(n>1) {
        sd=sqrt( (sumsq/n - mean*mean) * n/(n-1) );
      } else sd=0;
      printf "%.4f %.4f %d\n", mean, sd, n;
    } else {
      printf "0 0 0\n";
    }
  }'
}

stats=$(compute_stats)
read mean sd count <<< "$stats"

if echo "$sd > 0" | bc -l >/dev/null 2>&1; then
  effect_size=$(echo "scale=2; $mean / $sd" | bc -l)
else
  effect_size=0.00
fi

echo "effect_size: $effect_size"
echo "participants_analyzed: $count"
EOF
bash /tmp/calc_all.sh
